def issue_qr_tokens(apps, schema_editor):
    Worker = apps.get_model("coordination", "Worker")
    for worker in Worker.objects.filter(qr_token__isnull=True):
        worker.qr_token = coordination.models.new_qr_token()
        worker.save(update_fields=["qr_token"])


def link_existing_skills(apps, schema_editor):
    """Create Skill rows from each worker's primary trade and comma-separated skills."""
    Skill = apps.get_model("coordination", "Skill")
    Worker = apps.get_model("coordination", "Worker")
    for worker in Worker.objects.all():
        names = [worker.primary_trade, *worker.skills.split(",")]
        for name in {value.strip()[:80] for value in names if value and value.strip()}:
            skill = Skill.objects.filter(name__iexact=name).first() or Skill.objects.create(name=name)
            worker.skill_set.add(skill)


